  var esc = function (s) { return String(s).replace(/[&<>"]/g, function (c) { return ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]; }); };

  ids.innerHTML = D.ids.map(function (i) {
    return '<div class="row' + (i.r === "control" ? " ctl" : "") + '"><b>' + esc(i.l) +
      (i.r === "control" ? '<span class="tag">control</span>' : "") + '</b><span class="who">' + esc(i.o) +
      '</span><span class="ua">' + esc(i.ua) + "</span></div>";
  }).join("");

  function cell(v) {
    if (!v || v[0] == null) return '<td class="no">no answer</td>';
    var status = v[0], words = v[1], blocked = v[2], shell = v[3];
    var cls = blocked ? "no" : shell ? "sh" : "ok";
    var what = blocked ? "blocked" : shell ? "shell" : "ok";
    return '<td class="' + cls + '">' + status + " " + what + "<br>" + (words == null ? "-" : words.toLocaleString()) + "w</td>";
  }

  function draw(filter) {
    var rows = D.tg.filter(function (t) { return filter === "all" || t.v === "measurable"; });
    var head = '<tr><th>target</th>' + D.ids.map(function (i) {
      return '<th' + (i.r === "control" ? ' class="ctl"' : "") + ">" + esc(i.l) + "</th>";
    }).join("") + "</tr>";
    matrix.innerHTML = head + rows.map(function (t) {
      return '<tr class="' + t.v + '"><td class="site"><b>' + esc(t.k) + '</b><span>' + esc(t.n) +
        '</span><span class="ua-verdict">' + t.v + "</span></td>" +
        D.ids.map(function (i) { return cell(t.r[i.k]); }).join("") + "</tr>";
    }).join("");
    // Control COLUMNS are marked here rather than in the cell builder, because the
    // builder returns one cell without knowing which column it lands in.
    Array.prototype.forEach.call(matrix.rows, function (row) {
      D.ids.forEach(function (i, n) {
        if (i.r === "control" && row.cells[n + 1]) row.cells[n + 1].classList.add("ctl");
      });
    });
  }

  // The Web Bot Auth enforcement probe, rendered as a paired comparison. Same
  // user-agent, one row carrying a Signature-Agent pointer and one carrying
  // nothing. A difference in either column is an origin that parsed the header.
  var wba = document.getElementById("ua-wba");
  if (wba) {
    var rows = D.tg.filter(function (t) { return t.v === "measurable"; });
    var diffs = 0;
    var html = '<div class="r h"><span>target</span><span>ua-survey, no header</span><span>ua-survey + Signature-Agent</span></div>' +
