        var plain = t.r.honest, probe = t.r.wba_unsigned;
        if (!plain || !probe) return "";
        var same = plain[0] === probe[0] && plain[1] === probe[1];
        if (!same) diffs++;
        var fmt = function (v) { return v[0] + " " + (v[2] ? "blocked" : v[3] ? "shell" : "ok") + ", " + (v[1] == null ? "-" : v[1].toLocaleString()) + "w"; };
        return '<div class="r"><span class="t">' + esc(t.k) + '</span><span class="v same">' + fmt(plain) +
          '</span><span class="v ' + (same ? "same" : "diff") + '">' + fmt(probe) + "</span></div>";
      }).join("");
    wba.innerHTML = html + '<div class="verdict"><b>' + diffs + " of " + rows.length +
      " measurable targets answered the two differently.</b> " + (diffs === 0
        ? "Every one served the signature pointer exactly what it served the bare string, to the word. Nothing in this sample read the header."
        : "Something parsed the header, so the reading above needs revisiting against those rows.") + "</div>";
  }

  if (toggle) {
    toggle.addEventListener("click", function (e) {
      var b = e.target.closest("button");
      if (!b) return;
      Array.prototype.forEach.call(toggle.querySelectorAll("button"), function (x) { x.classList.toggle("on", x === b); });
      draw(b.getAttribute("data-f"));
    });
  }
